[s1, h1] = sload('gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf'); %[output:06e776fb]

% sample rate = 512 Hz
% 17 channels
% 172032
%%
[s2, h2] = sload('gdfs/ah7.20170613.162331.offline.mi.mi_bhbf.gdf');

% sample rate = 512 Hz
% 17 channels
% size 162816
%%
[s3, h3] = sload('gdfs/ah7.20170613.162934.offline.mi.mi_bhbf.gdf');

% sample rate = 512 Hz
% 17 channels
% size 165888
%%
% Now that we know the files are all structured the same we can concatenate
N_GDFS = 3;
hs = cell(N_GDFS, 1);
hs{1} = h1;
hs{2} = h2;
hs{3} = h3;
%%
s = [s1; s2; s3];
sizes = [size(s1, 1); size(s2, 1); size(s3, 1)];
offsets = cumsum(sizes);
h = h1;

for i = 2:N_GDFS % 1 is already included
    h.EVENT.POS = [h.EVENT.POS; hs{i}.EVENT.POS + offsets(i-1)];
    h.EVENT.DUR = [h.EVENT.DUR; hs{i}.EVENT.DUR];
    h.EVENT.TYP = [h.EVENT.TYP; hs{i}.EVENT.TYP];
end
%%
trial = 0;
Tk = zeros(size(s, 1), 1);
Fk = zeros(size(s, 1), 1);
Ak = zeros(size(s, 1), 1);
CFk = zeros(size(s, 1), 1);
Xk = zeros(size(h.EVENT.POS, 1) / 4, 1);
Rk = zeros(size(s, 1), 1);

last_pos = 1;
for i = 1:size(sizes, 1)
    Rk(last_pos:offsets(i)) = i;
    last_pos = offsets(i) + 1;
end

for i = 1:size(h.EVENT.POS, 1)
    if i > 1 && Rk(h.EVENT.POS(i-1)) ~= Rk(h.EVENT.POS(i))
        trial = 0;
    end
    switch h.EVENT.TYP(i)
        case 1 % start
            startTrialIdx = h.EVENT.POS(i);
            trial = trial + 1;
        case 786 % fixation
            fixationStartIdx = h.EVENT.POS(i);
            fixationEndIdx = fixationStartIdx + h.EVENT.DUR(i) - 1;
            Fk(fixationStartIdx:fixationEndIdx) = h.EVENT.TYP(i);
        case 771 % cue (both feet)
            cueStartIdx = h.EVENT.POS(i);
            cueEndIdx = cueStartIdx + h.EVENT.DUR(i) - 1;
            Ak(cueStartIdx:cueEndIdx) = h.EVENT.TYP(i);
        case 773 % cue (both hand)
            cueStartIdx = h.EVENT.POS(i);
            cueEndIdx = cueStartIdx + h.EVENT.DUR(i) - 1;
            Ak(cueStartIdx:cueEndIdx) = h.EVENT.TYP(i);
        case 781 % feedback
            feedbackStartIdx = h.EVENT.POS(i);
            feedbackEndIdx = feedbackStartIdx + h.EVENT.DUR(i) - 1;
            CFk(feedbackStartIdx:feedbackEndIdx) = h.EVENT.TYP(i);
            Tk(startTrialIdx:feedbackEndIdx) = trial;
        otherwise
            error('Weird stuff in GDFs');
    end
end
%%
channels = [7, 9, 11]; % C3, Cz, C4
SampleRate = 512;

muButter = [8 13];
betaButter = [13 30];

sc = s(:, channels);

[bmu, amu] = butter(3, 2 * muButter / SampleRate);
[bbe, abe] = butter(3, 2 * betaButter / SampleRate);
sfiltmu = filtfilt(bmu, amu, sc);
sfiltbe = filtfilt(bbe, abe, sc);

plot(sc, 'r'); %[output:8d321bcd]
hold on; %[output:8d321bcd]
plot(sfiltmu, 'b'); %[output:8d321bcd]
plot(sfiltbe, 'g'); %[output:8d321bcd]
hold off; %[output:8d321bcd]
%%
% filterAnalyzer(bmu, amu, 'SampleRates', SampleRate);
%%
% filterAnalyzer(bbe, abe, 'SampleRates', SampleRate);
%%
smu = sfiltmu .^ 2;
sbe = sfiltbe .^ 2;

windowSize = 512; % 1 sec
b = (1 / windowSize) * ones(1, windowSize);
a = 1;

smu_filtered = filter(b, a, smu);
sbe_filtered = filter(b, a, sbe);

lsf_mu = log(smu_filtered);
lsf_be = log(sbe_filtered);
%%
plot(lsf_mu(50:end, :)); %[output:55f149b6]
%%
plot(lsf_be(50:end, :)); %[output:6ae5b134]
%%
plot(s(1:8*SampleRate, channels)); %[output:63c27876]
%%
plot(lsf_mu(50:8*SampleRate, :)); %[output:15037254]
%%
plot(lsf_be(50:8*SampleRate, :)); %[output:9570bd81]

